import{_ as i,a0 as a,w as s,s as u,ao as l,I as n,x as d,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux 命令行简介 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 命令行简介 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 命令行简介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 命令行简介 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200131 Intro to the Linux command line","title":"Linux 命令行简介","tag":"202002","desc":""},"relativePath":"202002/20200131 Intro to the Linux command line.md","filePath":"[post].md"}'),p={name:"202002/20200131 Intro to the Linux command line.md"};function m(c,t,h,x,w,T){const e=a("Link");return s(),u("div",null,[t[18]||(t[18]=l('<h1 id="linux-命令行简介" tabindex="-1">Linux 命令行简介 <a class="header-anchor" href="#linux-命令行简介" aria-label="Permalink to “Linux 命令行简介”">​</a></h1><blockquote><p>下面是一些针对刚开始使用 Linux 命令行的人的热身练习。警告：它可能会上瘾。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2020/01/cmd_linux-control_linux-logo_-100828420-large.jpg" alt=""></p><p>如果你是 Linux 新手，或者从来没有花时间研究过命令行，你可能不会理解为什么这么多 Linux 爱好者坐在舒适的桌面前兴奋地输入命令来使用大量工具和应用。在这篇文章中，我们将快速浏览一下命令行的奇妙之处，看看能否让你着迷。</p><p>首先，要使用命令行，你必须打开一个命令工具（也称为“命令提示符”）。如何做到这一点将取决于你运行的 Linux 版本。例如，在 RedHat 上，你可能会在屏幕顶部看到一个 “Activities” 选项卡，它将打开一个选项列表和一个用于输入命令的小窗口（类似 “cmd” 为你打开的窗口）。在 Ubuntu 和其他一些版本中，你可能会在屏幕左侧看到一个小的终端图标。在许多系统上，你可以同时按 <code>Ctrl+Alt+t</code> 键打开命令窗口。</p><p>如果你使用 PuTTY 之类的工具登录 Linux 系统，你会发现自己已经处于命令行界面。</p><p>一旦你得到你的命令行窗口，你会发现自己坐在一个提示符面前。它可能只是一个 <code>$</code> 或者像 <code>user@system:~$</code> 这样的东西，但它意味着系统已经准备好为你运行命令了。</p>',7)),n("p",null,[t[1]||(t[1]=d("一旦你走到这一步，就应该开始输入命令了。下面是一些要首先尝试的命令，以及这里是一些特别有用的命令的 ",-1)),o(e,{href:"https://www.networkworld.com/article/3391029/must-know-linux-commands.html"},{default:r(()=>[...t[0]||(t[0]=[d("PDF",-1)])]),_:1}),t[2]||(t[2]=d(" 和适合打印和做成卡片的双面命令手册。",-1))]),t[19]||(t[19]=l('<div class="table-wrap"><table><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>pwd</code></td><td>显示我在文件系统中的位置（在最初进入系统时运行将显示主目录）</td></tr><tr><td><code>ls</code></td><td>列出我的文件</td></tr><tr><td><code>ls -a</code></td><td>列出我更多的文件（包括隐藏文件）</td></tr><tr><td><code>ls -al</code></td><td>列出我的文件，并且包含很多详细信息（包括日期、文件大小和权限）</td></tr><tr><td><code>who</code></td><td>告诉我谁登录了（如果只有你，不要失望）</td></tr><tr><td><code>date</code></td><td>日期提醒我今天是星期几（也显示时间）</td></tr><tr><td><code>ps</code></td><td>列出我正在运行的进程（可能只是你的 shell 和 <code>ps</code> 命令）</td></tr></tbody></table></div><p>一旦你从命令行角度习惯了 Linux 主目录之后，就可以开始探索了。也许你会准备好使用以下命令在文件系统中闲逛：</p><div class="table-wrap"><table><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>cd /tmp</code></td><td>移动到其他文件夹（本例中，打开 <code>/tmp</code> 文件夹）</td></tr><tr><td><code>ls</code></td><td>列出当前位置的文件</td></tr><tr><td><code>cd</code></td><td>回到主目录（不带参数的 <code>cd</code> 总是能将你带回到主目录）</td></tr><tr><td><code>cat .bashrc</code></td><td>显示文件的内容（本例中显示 <code>.bashrc</code> 文件的内容）</td></tr><tr><td><code>history</code></td><td>显示最近执行的命令</td></tr><tr><td><code>echo hello</code></td><td>跟自己说 “hello”</td></tr><tr><td><code>cal</code></td><td>显示当前月份的日历</td></tr></tbody></table></div><p>要了解为什么高级 Linux 用户如此喜欢命令行，你将需要尝试其他一些功能，例如重定向和管道。“重定向”是当你获取命令的输出并将其放到文件中而不是在屏幕上显示时。“管道”是指你将一个命令的输出发送给另一条将以某种方式对其进行操作的命令。这是可以尝试的命令：</p><div class="table-wrap"><table><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>echo &quot;echo hello&quot; &gt; tryme</code></td><td>创建一个新的文件并将 “echo hello” 写入该文件</td></tr><tr><td><code>chmod 700 tryme</code></td><td>使新建的文件可执行</td></tr><tr><td><code>tryme</code></td><td>运行新文件（它应当运行文件中包含的命令并且显示 “hello” ）</td></tr><tr><td><code>ps aux</code></td><td>显示所有运行中的程序</td></tr><tr><td>`ps aux</td><td>grep $USER`</td></tr><tr><td><code>echo $USER</code></td><td>使用环境变量显示你的用户名</td></tr><tr><td><code>whoami</code></td><td>使用命令显示你的用户名</td></tr><tr><td>`who</td><td>wc -l`</td></tr></tbody></table></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>一旦你习惯了基本命令，就可以探索其他命令并尝试编写脚本。 你可能会发现 Linux 比你想象的要强大并且好用得多.</p><hr>',8)),n("p",null,[t[4]||(t[4]=d("via: ",-1)),o(e,{href:"https://www.networkworld.com/article/3518440/intro-to-the-linux-command-line.html"},{default:r(()=>[...t[3]||(t[3]=[d("https://www.networkworld.com/article/3518440/intro-to-the-linux-command-line.html",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=d("作者：",-1)),o(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:r(()=>[...t[5]||(t[5]=[d("Sandra Henry-Stocker",-1)])]),_:1}),t[10]||(t[10]=d(" 选题：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[6]||(t[6]=[d("lujun9972",-1)])]),_:1}),t[11]||(t[11]=d(" 译者：",-1)),o(e,{href:"https://github.com/qianmingtian"},{default:r(()=>[...t[7]||(t[7]=[d("qianmingtian",-1)])]),_:1}),t[12]||(t[12]=d(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[8]||(t[8]=[d("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=d("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[d("LCTT",-1)])]),_:1}),t[16]||(t[16]=d(" 原创编译，",-1)),o(e,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[d("Linux中国",-1)])]),_:1}),t[17]||(t[17]=d(" 荣誉推出",-1))])])}const g=i(p,[["render",m]]);export{f as __pageData,g as default};
